  eapply rz_msteps; [exact MH | exact ML | exact MS | exact RZ].
Qed.
Lemma bbe_tail : forall fr0 fr cs C A A5 Ab m mb mdb regs0 R (s w h d skel arrs rkel arrr : Z) (rowss rowsr : Z -> Z) (ret : word) (S : TSet) (kR bR k b : Z),
